var PICKER_ID='chainProxyPreferredPicker',SELECT_ID='chainProxyPreferredSelect',FILTER_ID='chainProxyPreferredFilter',AUTO_ID='chainProxyPreferredAuto',RES_COUNT_ID='chainProxyPreferredResidentialCount',META_KEY='edgetunnel.chain.tools.v1',installed=false,state=null;
