function loadMeta(){try{var saved=JSON.parse(localStorage.getItem(META_KEY)||'{}');return saved&&saved.meta&&typeof saved.meta==='object'?saved.meta:{}}catch(error){return{}}}
function metaForEntry(entry,meta){meta=meta||loadMeta();var base=entryKey(entry),exact=String(entry.index)+'|'+base;if(meta[exact])return meta[exact];if(meta[base])return meta[base];var keys=Object.keys(meta);for(var i=0;i<keys.length;i++){var key=String(keys[i]).toLowerCase();if(key.slice(-(base.length+1))==='|'+base)return meta[keys[i]]}return null}
