function apply(option){var host=el('chainProxyHost'),port=el('chainProxyPort');if(!option||!host)return;host.value=option.dataset.host||'';if(port){port.value=option.dataset.port||'';if(typeof window.normalizeChainProxyPortInput==='function')window.normalizeChainProxyPortInput()}}
